import { supabaseAdmin } from "../../utils/supabaseAdmin";
import { sendPushToTokens, PushPayload } from "../../utils/fcm";

// ─── Generic notification worker ────────────────────────────
// One SQS queue (NotificationQueue) carries EVERY push scenario. Each job has a
// `type` that this worker switches on to build the copy + in-app row. Adding a
// new scenario = add one entry to `templates` and enqueue with that type — no
// new queue, no new worker, no new FCM code (we reuse utils/fcm).
//
// Job shapes on the queue (all handled by the same worker):
//   • single user:   { type, user_id, data? }
//   • many users:    { type, user_ids: string[], data? }          // same copy for all
//   • per-recipient: { type, data?, recipients: [{ user_id, data? }] }
//                        └ each recipient's `data` is merged OVER the shared `data`,
//                          so templates can read names/values unique to that user.
//
// `data` is what templates interpolate — put names here (courseName, facultyName,
// the student's own name, …). Shared values go in top-level `data`; values that
// differ per user go in that recipient's `data`.

interface NotificationTemplate {
    // notifications.type is the `notification_type` enum — must be a valid label.
    notifType:
        | "COINS_EARNED"
        | "STREAK_REMINDER"
        | "BADGE_UNLOCKED"
        | "COURSE_UPDATE"
        | "EXAM_REMINDER";
    title: string;
    body: string;
    // Extra string map delivered to the app for deep-linking.
    pushData?: Record<string, string>;
}

const templates: Record<string, (data: any) => NotificationTemplate> = {
    // Student completed the streak goal and earned coins.
    STREAK_REWARD: (d) => ({
        notifType: "COINS_EARNED",
        title: `🔥 ${d?.days ?? ""}-day streak!`.replace(/\s+/g, " ").trim(),
        body: `You earned ${d?.coins ?? 0} coins — keep it going!`,
        pushData: {
            type: "STREAK_REWARD",
            coins: String(d?.coins ?? 0),
            days: String(d?.days ?? 0),
        },
    }),

    // Student missed a day and lost their streak — re-engagement nudge.
    STREAK_BROKEN: () => ({
        notifType: "STREAK_REMINDER",
        title: "💔 You lost your streak",
        body: "Start a new one today!",
        pushData: { type: "STREAK_BROKEN" },
    }),

    // Faculty uploaded / updated a course — fan out to enrolled students.
    // Enqueue with `user_ids` (all students) + shared data { courseName, facultyName,
    // courseId }. Add a per-recipient { name } if you want to greet each student.
    COURSE_UPDATE: (d) => ({
        notifType: "COURSE_UPDATE",
        title: d?.name ? `Hi ${d.name}! New course material 📚` : "New course material 📚",
        body: `${d?.facultyName ?? "Your faculty"} added "${d?.courseName ?? "a course"}".`,
        pushData: {
            type: "COURSE_UPDATE",
            ...(d?.courseId ? { courseId: String(d.courseId) } : {}),
        },
    }),
};

// One recipient with the copy already built for them (data may be shared or
// personalised, so each recipient can carry different copy).
interface BuiltRecipient {
    userId: string;
    tpl: NotificationTemplate;
    data: Record<string, any>;
}

// Normalise every job shape (user_id | user_ids | recipients) into a flat list of
// { userId, data } where data is the recipient's own values merged OVER shared.
const normalizeRecipients = (
    job: any
): { userId: string; data: Record<string, any> }[] => {
    const shared: Record<string, any> = job?.data ?? {};
    const out: { userId: string; data: Record<string, any> }[] = [];

    if (Array.isArray(job?.recipients)) {
        for (const r of job.recipients) {
            if (r?.user_id) out.push({ userId: r.user_id, data: { ...shared, ...(r.data ?? {}) } });
        }
    }
    if (Array.isArray(job?.user_ids)) {
        for (const id of job.user_ids) {
            if (id) out.push({ userId: id, data: shared });
        }
    }
    if (job?.user_id) out.push({ userId: job.user_id, data: shared });

    // De-dupe by userId (first occurrence — recipient-specific data wins).
    const seen = new Set<string>();
    return out.filter((r) => (seen.has(r.userId) ? false : seen.add(r.userId)));
};

// ─── bulk in-app notification rows (mirrors the video/chat pattern) ─
const createNotifications = async (built: BuiltRecipient[]) => {
    if (built.length === 0) return;
    const now = new Date().toISOString();
    const { error } = await supabaseAdmin.from("notifications").insert(
        built.map((b) => ({
            user_id: b.userId,
            type: b.tpl.notifType,
            title: b.tpl.title,
            body: b.tpl.body,
            data: b.data ?? null,
            is_admin: false,
            sent_at: now,
        }))
    );
    if (error) console.log("createNotifications error", error);
};

// ─── one queue message → one (possibly multi-recipient) push fan-out ───
const processRecord = async (record: any) => {
    const job = JSON.parse(record.body);
    const { type } = job ?? {};

    const build = type ? templates[type] : undefined;
    const recipients = normalizeRecipients(job);

    if (!build || recipients.length === 0) {
        // Unknown type or no recipient — drop it (don't retry a bad job).
        console.log("notificationWorker: skipping unactionable job", job);
        return;
    }

    // Build each recipient's copy (cheap string work — supports per-user names).
    const built: BuiltRecipient[] = recipients.map((r) => ({
        userId: r.userId,
        tpl: build(r.data),
        data: r.data,
    }));

    // Leave one in-app row per recipient (single insert).
    await createNotifications(built);

    // Pull active device tokens for every recipient in one query.
    const userIds = built.map((b) => b.userId);
    const { data: devices, error: devErr } = await supabaseAdmin
        .from("notification_devices")
        .select("user_id, token")
        .in("user_id", userIds)
        .eq("is_active", true);

    if (devErr) throw new Error(devErr.message);

    // user_id → its active tokens.
    const tokensByUser = new Map<string, string[]>();
    for (const d of devices ?? []) {
        if (!d?.token) continue;
        const list = tokensByUser.get(d.user_id) ?? [];
        list.push(d.token);
        tokensByUser.set(d.user_id, list);
    }

    // Group recipients that share identical copy into one FCM multicast, so a
    // same-copy blast (e.g. a course update to 500 students) is one send, while
    // personalised copy still fans out per distinct message.
    const groups = new Map<string, { payload: PushPayload; tokens: string[] }>();
    for (const b of built) {
        const tokens = tokensByUser.get(b.userId);
        if (!tokens || tokens.length === 0) continue; // no registered device
        const payload: PushPayload = {
            title: b.tpl.title,
            body: b.tpl.body,
            data: b.tpl.pushData ?? {},
        };
        const key = `${payload.title}�${payload.body}�${JSON.stringify(payload.data)}`;
        const g = groups.get(key) ?? { payload, tokens: [] };
        g.tokens.push(...tokens);
        groups.set(key, g);
    }

    if (groups.size === 0) return; // nobody has a device

    const results = await Promise.all(
        [...groups.values()].map((g) => sendPushToTokens(g.tokens, g.payload))
    );

    // Deactivate dead tokens so we stop trying them next time.
    const invalidTokens = results.flatMap((r) => r.invalidTokens);
    if (invalidTokens.length) {
        await supabaseAdmin
            .from("notification_devices")
            .update({ is_active: false })
            .in("token", invalidTokens);
    }
};

export const notificationRepository = {
    // SQS consumer. Returns { batchItemFailures } so ReportBatchItemFailures
    // retries only the records that actually failed.
    processQueue: async (event: any) => {
        const results = await Promise.allSettled(
            event.Records.map((record: any) => processRecord(record))
        );

        const failures = results
            .map((r, i) => ({ result: r, record: event.Records[i] }))
            .filter(({ result }) => result.status === "rejected")
            .map(({ record }) => ({ itemIdentifier: record.messageId }));

        return { batchItemFailures: failures };
    },
};
